import sys
import { Pipe } from sys
export fn child() -> Pipe {
  var guard = sys.Pipe(2147483644, 2147483645)
  defer {
    guard.closeRead()
    guard.closeWrite()
  }
  Coro.yield()
  Coro.yield()
  var result = sys.Pipe(2147483646, 2147483647)
  return result
}

