import sys
import { Pipe } from sys
import { child } from "./library"
fn answer() -> i64 {
  var live = child()
  defer {
    live.closeRead()
    live.closeWrite()
  }
  Coro.yield()
  Coro.yield()
  return live.readEnd() - 2147483604
